<script setup lang="ts">
import SelectField from '../../components/SelectField.vue'
import { computed, ref } from 'vue'
import { Plus, RefreshCw, Search, Play, Pencil, Trash2, ExternalLink, FolderSync, ArrowUpRight, Layers3 } from '@lucide/vue'
import SourceEditor from './SourceEditor.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { clone, state, perform, refresh, runSource, saveConfiguration, notify } from '../../app/state'
import type { Source } from '../../app/types'
import { time, bytes } from '../../app/format'
const search = ref(''); const type = ref(''); const edit = ref<Source | undefined>(); const showEditor = ref(false)
const sources = computed(()=>state.config?.config.sources.filter(source=>(!type.value||source.type===type.value)&&`${source.name} ${source.id} ${source.dest}`.toLowerCase().includes(search.value.toLowerCase()))??[])
const active = computed(()=>state.runs.filter(run=>['running','queued','pausing'].includes(run.state)).length)
function latest(id: string) { return state.runs.find(run=>run.source_id===id) }
function published(id: string) { return state.info?.publications.find(p=>p.source_id===id) }
function editSource(source?: Source) { edit.value=source; showEditor.value=true }
async function remove(source: Source) { if (!window.confirm(`删除同步源“${source.name}”？已保存的文件与运行记录会保留。`)) return; if (!state.config) return; const config=clone(state.config.config); config.sources=config.sources.filter(item=>item.id!==source.id); await saveConfiguration(config) }
function url(dest: string) { return '/'+dest.split('/').map(encodeURIComponent).join('/')+'/' }
async function copy(dest: string) { await navigator.clipboard.writeText(new URL(url(dest),location.origin).href); notify('镜像地址已复制') }
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">SOURCE WORKSPACE</span><h1>同步源<span>.</span></h1><p>让上游软件，成为你本地可靠的镜像。</p></div><div class="heading-actions"><button class="button" @click="perform(refresh)"><RefreshCw :size="16"/>刷新</button><button class="button primary" @click="editSource()"><Plus :size="17"/>新增同步源</button></div></div><div class="stat-grid"><article><span>同步源</span><strong>{{state.config?.config.sources.length??0}}<small>个</small></strong><FolderSync :size="24"/></article><article><span>正在运行</span><strong>{{active}}<small>个任务</small></strong><Layers3 :size="24"/></article><article><span>已发布镜像</span><strong>{{state.info?.publications.length??0}}<small>个</small></strong><ArrowUpRight :size="24"/></article><article><span>本次启动分发</span><strong class="bytes-stat">{{bytes(state.info?.downloads.bytes??0)}}</strong><small>{{state.info?.downloads.active??0}} 条活动下载</small></article></div><div class="panel"><div class="filter-toolbar"><label class="search-field"><Search :size="17"/><input v-model="search" placeholder="搜索名称、标识或目录…" aria-label="搜索同步源"/></label><SelectField v-model="type" aria-label="筛选同步方式" :options="[{ value: '', label: '全部同步方式' }, { value: 'rsync', label: 'rsync' }, { value: 'reposync', label: 'reposync' }, { value: 'github_release', label: 'GitHub Release' }]" /><span class="filter-count">{{sources.length}} 个源</span></div><div class="table-scroll"><table class="source-table"><thead><tr><th>同步源</th><th>来源与目录</th><th>最近运行</th><th>镜像发布</th><th class="right">操作</th></tr></thead><tbody><tr v-for="source in sources" :key="source.id"><td><div class="source-name"><span class="source-mark" :class="source.type"><FolderSync :size="20"/></span><div><strong>{{source.name}}</strong><small>{{source.id}}<span class="enabled-dot" :class="{disabled:!source.enabled}">{{source.enabled?'已启用':'已禁用'}}</span></small></div></div><span class="type-pill">{{source.type==='github_release'?'GitHub Release':source.type}}</span></td><td><code class="source-origin">{{source.type==='github_release'?source.github_release.repository:source.upstreams.src1}}</code><small class="dest">/{{source.dest}}/</small><span v-if="Object.keys(source.upstreams).length>1" class="backup-count">{{Object.keys(source.upstreams).length-1}} 个备用来源</span></td><td><StatusBadge v-if="latest(source.id)" :state="latest(source.id)!.state"/><span v-else class="muted">尚未运行</span><small>{{time(latest(source.id)?.created_at)}}</small></td><td><a v-if="published(source.id)" :href="url(source.dest)" target="_blank" rel="noopener" class="published-link">已发布<ExternalLink :size="13"/></a><span v-else class="muted">等待首次同步</span><button v-if="published(source.id)" class="text-button" @click="perform(()=>copy(source.dest))">复制 baseurl</button></td><td class="right"><div class="row-actions"><button class="button compact" :disabled="!source.enabled" @click="perform(()=>runSource(source.id))"><Play :size="14"/>同步</button><button class="icon-button" :aria-label="'编辑 '+source.name" @click="editSource(source)"><Pencil :size="16"/></button><button class="icon-button danger" :aria-label="'删除 '+source.name" @click="perform(()=>remove(source))"><Trash2 :size="16"/></button></div></td></tr><tr v-if="!sources.length"><td colspan="5" class="empty-state"><FolderSync :size="32"/><h3>这里还没有同步源</h3><p>新增一个源，或调整当前搜索条件。</p><button class="button primary" @click="editSource()"><Plus :size="16"/>新增同步源</button></td></tr></tbody></table></div></div><div class="page-note"><span class="note-dot"></span>同步到私有工作目录，成功校验后发布。公共镜像继续提供上一版文件。</div><SourceEditor v-if="showEditor" :source="edit" @close="showEditor=false"/></section></template>
